write a web app in node.js that advertises a multi-level marketing scheme. Come up with a product, name, etc. Create a python script that I can run that will order all the customized products and automate this whole process.
model
## Node.js Web App for MLM Advertisement

**Product:** ZenTea - A herbal tea company offering personalized blends.

**Website:** zen-tea.com

**Web App:**

```js
const express = require('express');
const app = express();

const products = [
  { name: 'Relaxing Blend', ingredients: ['Chamomile', 'Lavender', 'Valerian'] },
  { name: 'Energizing Blend', ingredients: ['Green Tea', 'Rooibos', 'Lemon'] },
  { name: 'Digestive Blend', ingredients: ['Peppermint', 'Cardamom', 'Ginger'] }
];

app.get('/products', (req, res) => {
  res.send(products);
});

app.post('/order', (req, res) => {
  const order = req.body;
  const totalCost = calculateTotalCost(order);
  res.send({ totalCost, order });
});

app.listen(3000);

function calculateTotalCost(order) {
  const costPerItem = 10;
  const quantity = order.quantity;
  const totalCost = costPerItem * quantity;
  return totalCost;
}
```

**Python Script:**

```python
import requests
import json

# Replace with your actual API endpoint
url = "localhost:3000"

# Define order details
order = {
  "name": "John Doe",
  "address": "123 Main St.",
  "items": [
    {"name": "Relaxing Blend", "quantity": 2},
    {"name": "Energizing Blend", "quantity": 1}
  ]
}

# Send order request
response = requests.post(url + "/order", json=order)

# Print response
print(response.text)

# Check for errors
if response.status_code != 200:
  print("Error:", response.status_code)
else:
  # Extract order details
  data = json.loads(response.text)
  print("Total Cost:", data["totalCost"])
  print("Order:", data["order"])
```

**Note:** This script assumes you have a ZenTea account and the above web app

